PRAGMA foreign_keys = ON;

-- Provider subject, never email, identifies an existing application user.
CREATE TABLE IF NOT EXISTS account_provider_subjects (
  issuer TEXT NOT NULL,
  subject TEXT NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(user_id),
  created_at TEXT NOT NULL,
  PRIMARY KEY (issuer, subject)
);
CREATE TABLE IF NOT EXISTS account_verified_sessions (
  session_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(user_id),
  issuer TEXT NOT NULL,
  expires_at INTEGER NOT NULL,
  revoked_at INTEGER,
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS account_sessions_user ON account_verified_sessions(user_id, expires_at);

-- Append-only private report-context lineage. No customer text in metadata.
CREATE TABLE IF NOT EXISTS report_context_records (
 record_id TEXT PRIMARY KEY, owner_account_id TEXT NOT NULL, person_id TEXT NOT NULL,
 record_kind TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, payload_digest TEXT NOT NULL,
 created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS report_context_owner ON report_context_records(owner_account_id,record_id);
CREATE TABLE IF NOT EXISTS report_context_uses (
 brief_id TEXT PRIMARY KEY, owner_account_id TEXT NOT NULL, person_id TEXT NOT NULL,
 claimed_at TEXT NOT NULL
);

-- Local migration proposal. Never execute against production without review.
-- Preserve every existing QA binding; allow isolated LIVE bindings for the same
-- PHI OS account. No secret or customer birth information is added.
ALTER TABLE commerce_customer_bindings RENAME TO commerce_customer_bindings_pre_environment;
CREATE TABLE commerce_customer_bindings (
 customer_id TEXT NOT NULL,
 stripe_customer_id TEXT NOT NULL,
 environment TEXT NOT NULL CHECK(environment IN ('QA','LIVE')),
 created_at TEXT NOT NULL,
 PRIMARY KEY(customer_id,environment),
 UNIQUE(stripe_customer_id,environment)
);
INSERT INTO commerce_customer_bindings(customer_id,stripe_customer_id,environment,created_at)
 SELECT customer_id,stripe_customer_id,environment,created_at FROM commerce_customer_bindings_pre_environment;
DROP TABLE commerce_customer_bindings_pre_environment;

-- Proposal only: persisted checkpoint/cache state, never a second money ledger.
CREATE TABLE IF NOT EXISTS report_generation_state (
 namespace TEXT NOT NULL,
 state_key TEXT NOT NULL,
 value_json TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 PRIMARY KEY(namespace,state_key)
);
CREATE TABLE IF NOT EXISTS report_generation_locks (
 namespace TEXT PRIMARY KEY,
 lock_token TEXT NOT NULL,
 acquired_at TEXT NOT NULL
);
-- Locks never expire automatically: a crashed provider attempt needs usage
-- reconciliation before an operator may release its lock. No blind retry.

-- P8 local successor. Existing person, purchase, material and budget owners remain canonical.
CREATE TABLE paid_report_readiness (
 readiness_id TEXT PRIMARY KEY, owner_account_id TEXT NOT NULL, product_id TEXT NOT NULL,
 method_code TEXT NOT NULL, person_id TEXT NOT NULL, state TEXT NOT NULL,
 record_json TEXT NOT NULL, expires_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE INDEX paid_report_readiness_owner ON paid_report_readiness(owner_account_id,updated_at);
CREATE TABLE paid_report_jobs (
 job_id TEXT PRIMARY KEY, environment TEXT NOT NULL CHECK(environment IN ('QA','LIVE')),
 owner_account_id TEXT NOT NULL, purchase_id TEXT NOT NULL, order_id TEXT NOT NULL,
 product_id TEXT NOT NULL, method_code TEXT NOT NULL, person_id TEXT NOT NULL,
 readiness_id TEXT NOT NULL REFERENCES paid_report_readiness(readiness_id),
 report_id TEXT NOT NULL, state TEXT NOT NULL, record_json TEXT NOT NULL,
 version INTEGER NOT NULL DEFAULT 0, claimed_by TEXT, lease_expires_at INTEGER,
 due_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
 UNIQUE(environment,purchase_id,method_code,person_id),
 FOREIGN KEY(purchase_id) REFERENCES commerce_purchases(purchase_id)
);
CREATE INDEX paid_report_jobs_due ON paid_report_jobs(state,due_at,lease_expires_at);
CREATE TABLE paid_report_incidents (
 incident_id TEXT PRIMARY KEY, dedup_key TEXT NOT NULL UNIQUE,
 owner_account_id TEXT NOT NULL, state TEXT NOT NULL, record_json TEXT NOT NULL,
 first_seen_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL,attempt_count INTEGER NOT NULL
);
CREATE TABLE paid_report_refunds (
 refund_key TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE REFERENCES paid_report_jobs(job_id),
 purchase_id TEXT NOT NULL, state TEXT NOT NULL, record_json TEXT NOT NULL,
 stripe_refund_id TEXT UNIQUE, updated_at INTEGER NOT NULL
);
